  // ------------------------------------------------------------------ species (kp_data.js has the 22 of stage 1)
  // base { hp, atk, def, spd }: first stages ~190-260, middle ~280-330, final ~370-410, one-stage commons ~260-300,
  // rares ~320-360, breeding-only ~350-380, legendaries ~440-480. rate: how readily it likes a nut (commons 120-190,
  // uncommons 75-120, rares 45-60, legendaries 3-10). fur / nose / wing / pom: the robot's own colours; look: overrides
  const sp = (moogle, job, base, moves, o = {}) => Object.assign({ moogle, job, type: KP.JOBS[job].type, base, moves, rate: 120, exp: 60, curve: 'medium' }, o);
  const B = (hp, atk, def, spd) => ({ hp, atk, def, spd });
